    /**
     * Method to retrieve the Encounter via an EncounterPrimaryKey.
     * @param 	id Long
     * @return 	Encounter
     * @exception ProcessingException - Thrown if processing any related problems
     * @exception IllegalArgumentException 
     */
    @SuppressWarnings("unused")
    @QueryHandler
    public Encounter handle( FindEncounterQuery query ) 
    throws ProcessingException, IllegalArgumentException {
    	return find( query.getFilter().getEncounterId() );
    }
    
    /**
     * Method to retrieve a collection of all Encounters
     *
     * @param	query	FindAllEncounterQuery 
     * @return 	List<Encounter> 
     * @exception ProcessingException Thrown if any problems
     */
    @SuppressWarnings("unused")
    @QueryHandler
    public List<Encounter> handle( FindAllEncounterQuery query ) throws ProcessingException {
    	return findAll( query );
    }



/**
 * emit to subscription queries of type FindEncounter,
 * but only if the id matches
 *
 * @param		entity	Encounter
 */
	protected void emitFindEncounter( Encounter entity ) {
		LOGGER.info("handling emitFindEncounter" );
		
	    queryUpdateEmitter.emit(FindEncounterQuery.class,
	                            query -> query.getFilter().getEncounterId().equals(entity.getEncounterId()),
	                            entity);
	}
	
	/**
	 * unconditionally emit to subscription queries of type FindAllEncounter
	 * 
	 * @param		entity	Encounter
	 */
	protected void emitFindAllEncounter( Encounter entity ) {
		LOGGER.info("handling emitFindAllEncounter" );
		
	    queryUpdateEmitter.emit(FindAllEncounterQuery.class,
	                            query -> true,
	                            entity);
	}

